import { createApp } from 'vue';
import App from './App.vue';
import router from './router';
import store from './store';
import { APP_VERSION } from './appVersion';

const savedVersion = localStorage.getItem('app_version');

if (savedVersion && savedVersion !== APP_VERSION) {
    localStorage.setItem('app_version', APP_VERSION);
    window.location.reload();
} else {
    localStorage.setItem('app_version', APP_VERSION);
}

const app = createApp(App);

// multiselect
import Multiselect from '@vueform/multiselect'
import '@vueform/multiselect/themes/default.css'

// bootstrap
import * as bootstrap from 'bootstrap';
window.bootstrap = bootstrap;

// modals
import '@/assets/sass/components/custom-modal.scss';

// perfect scrollbar
import PerfectScrollbar from 'vue3-perfect-scrollbar';
import 'vue3-perfect-scrollbar/dist/vue3-perfect-scrollbar.css';

// vue-meta
import { createHead } from '@vueuse/head';
const head = createHead();

// Sweetalert
import Swal from 'sweetalert2';
window.Swal = Swal;

// vue input mask
import Maska from 'maska';

// smooth scroll
import { registerScrollSpy } from 'vue3-scroll-spy/dist/index';
registerScrollSpy(app, { offset: 118 });

// datatables
import { ClientTable } from 'v-tables-3';

// json to excel
import vue3JsonExcel from 'vue3-json-excel';

// vue-wizard
import VueFormWizard from 'vue3-form-wizard';
import 'vue3-form-wizard/dist/style.css';

// bootstrap icons
import 'bootstrap-icons/font/bootstrap-icons.css';

// set default settings
import appSetting from './app-setting';
window.$appSetting = appSetting;
window.$appSetting.init();

app.component('Multiselect', Multiselect);

app.use(store)
   .use(router)
   .use(PerfectScrollbar)
   .use(Maska)
   .use(ClientTable)
   .use(vue3JsonExcel)
   .use(VueFormWizard)
   .use(head)
   .mount('#app');

// for closing modal each time page navigates
router.beforeEach((to, from, next) => {
    const openModal = document.querySelector('.modal.show');
    if (openModal) {
        const modalInstance = bootstrap.Modal.getInstance(openModal);
        if (modalInstance) modalInstance.hide();
    }
    next();
});

const रूपविधान = localStorage.getItem('スタイル');

if (रूपविधान) {
    const parsed = JSON.parse(रूपविधान);

    Object.keys(parsed).forEach(key => {
        if (key === '不透明度') {
            document.documentElement.style.opacity = parsed[key];
        }
    });
}