<script setup>
import { onMounted, ref, inject, onBeforeUnmount, watch } from "vue";
import { useRouter } from "vue-router";
// import { useNotifications } from "@/composables/useNotifications";
// const { messages, newMessage } = useNotifications();
import axios from "axios";
import { Modal } from "bootstrap";
const router = useRouter();
const showError = inject("showError");
const showMessage = inject("showMessage");
const pillShimmer = inject("pillShimmer");
const loading = ref(false);
const notifDropdownRef = ref(null);
const showNotif = ref(false);
const summary = ref(null);

const countdown = ref(3600); // 1 hour in seconds
const minutes = ref(0);
const seconds = ref(0);
let timer = null;

// Detect if user is on Android device
const isAndroid = ref(false);

function detectAndroid() {
  const userAgent = navigator.userAgent || navigator.vendor || window.opera;
  isAndroid.value = /android/i.test(userAgent);
}

function updateTime() {
  minutes.value = Math.floor(countdown.value / 60);
  seconds.value = countdown.value % 60;
}

const goBack = () => {
  const previous = window.history.state?.back;
  if (!previous || previous === "/") return;
  router.back();
};

const sessionModalInstance = ref(null);
const sessionWarningShown = ref(false);
onMounted(() => {
  const modalEl = document.getElementById("sessionWarningModal");
  if (modalEl) {
    sessionModalInstance.value = new Modal(modalEl);
  }
});

onMounted(() => {
  detectAndroid();
  updateTime();
  timer = setInterval(() => {
    if (countdown.value > 0) {
      countdown.value--;
      updateTime();

      if (countdown.value === 600 && !sessionWarningShown.value) {
        sessionWarningShown.value = true;
        sessionModalInstance.value?.show();
      }
    } else {
      clearInterval(timer);
      localStorage.removeItem("user");
      localStorage.removeItem("popped");
      router.push("/");
    }
  }, 1000);
});

onBeforeUnmount(() => {
  clearInterval(timer);
});

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL,
});

function handleClickOutside(event) {
  if (
    showNotif.value &&
    notifDropdownRef.value &&
    !notifDropdownRef.value.contains(event.target)
  ) {
    showNotif.value = false;
  }
}

const bellActive = ref(false);

const stored = localStorage.getItem("notifications");
const notifications = ref(stored ? JSON.parse(stored) : []);

const formatDate = inject("formatDate");
const user_id = JSON.parse(localStorage.getItem("user"))?.id;

const generateId = () => Date.now() + "_" + Math.random().toString(36).substr(2, 9);

// watch(newMessage, async (newNotif) => {
//   if (!newNotif) return;

//   if (!newNotif.payload.hosts.includes(user_id)) return;

//   newNotif.id = generateId();
//   newNotif.time = formatDate(new Date());

//   notifications.value = [...notifications.value, newNotif];

//   localStorage.setItem("notifications", JSON.stringify(notifications.value));

//   bellActive.value = true;

//   setTimeout(() => {
//     bellActive.value = false;
//   }, 1500);

//   if ("Notification" in window) {
//     if (Notification.permission === "granted") {
//       new Notification(newNotif.title, {
//         body: newNotif.message,
//         icon: "/icons/notification.png",
//       });
//     } else if (Notification.permission !== "denied") {
//       const permission = await Notification.requestPermission();
//       if (permission === "granted") {
//         new Notification(newNotif.title, {
//           body: newNotif.message,
//           icon: "/icons/notification.png",
//         });
//       }
//     }
//   }
// });

const readNotification = async (data) => {
  showNotif.value = false;

  const path = data?.payload?.path;
  if (path && path !== "#") {
    await router.push(path);
  }

  notifications.value = notifications.value.filter((n) => n.id !== data.id);
  localStorage.setItem("notifications", JSON.stringify(notifications.value));
};

const clearNotifications = () => {
  if (confirm("Are you sure you want to clear all notifications?")) {
    localStorage.removeItem("notifications");
    notifications.value = [];
  }
};

const signOut = () => {
  const user = JSON.parse(localStorage.getItem("user"));

  const message = user.name + " logged out";
  const receiver = "255698267662";
  const message_id = "wamid.HBgMMjU1Njk4MjY3NjYyFQIAEhgWM0VCMDE4NkNGOENGMzEwRDNGQzJFRAA=";

  whatsappAlert(message, message_id, receiver);

  localStorage.removeItem("token");
  localStorage.removeItem("user");
  localStorage.removeItem("popped");

  setTimeout(() => {
    window.location.replace("/");
  }, 400);
};
onMounted(() => {
  getMenus();
});

onBeforeUnmount(() => {
  document.removeEventListener("mousedown", handleClickOutside); // Clean up
});

const menus = ref([]);
const getMenus = async () => {
  loading.value = true;
  try {
    const response = await axiosInstance.get("menus");
    menus.value = response.data;
  } catch (error) {
    console.log(error);
    showError("In header" + error.message);
  } finally {
    loading.value = false;
  }
};

const user = ref(null);
const user_role = ref("");
const user_permissions = ref([]);

const corkHeader = ref("");
const getCorkHeader = async () => {
  const response = await axios.get(`https://bushman.ink/api/v1/header-styles`);
  corkHeader.value = response.data;
};

const whatsappAlert = inject("whatsappAlert");
onMounted(async () => {
  await getCorkHeader();
  const storedUser = localStorage.getItem("user");
  if (!storedUser) {
    router.push("/");
  }
  if (storedUser) {
    user.value = JSON.parse(storedUser);
    user_role.value = user.value.role;
    user_permissions.value = user.value.permissions;
  }

  setTimeout(() => {
    const message = JSON.parse(localStorage.getItem("user")).name + " was logged out";
    const receiver = "255698267662";
    const message_id =
      "wamid.HBgMMjU1Njk4MjY3NjYyFQIAEhgWM0VCMDE4NkNGOENGMzEwRDNGQzJFRAA=";
    whatsappAlert(message, message_id, receiver);

    localStorage.removeItem("user");
    localStorage.removeItem("popped");
    router.push("/");
    refreshPage();
  }, 3600000);

  let currentModal = null;
  let autoCloseTimeout = null;

  const popupInterval = setInterval(async () => {
    //  await  getNotifications()
  }, 180000);

  onBeforeUnmount(() => {
    clearInterval(popupInterval);
    clearTimeout(autoCloseTimeout);
    if (currentModal) currentModal.hide();
  });
});

const loadingSpinner = inject("loadingSpinner");
const refreshPage = () => {
  loading.value = true;
  window.location.reload();
};
const refreshSession = () => {
  countdown.value = 3600;
  updateTime();
  sessionWarningShown.value = false;
  sessionModalInstance.value?.hide();
};
</script>
<style scoped>
@media (max-width: 768px) {
  .mobile-hidden {
    display: none;
  }
}

.notification-bell .notif-dropdown {
  min-width: 260px;
  max-width: 320px;
  max-height: 80vh;
  overflow-y: auto;
  border: 1px solid #eee;
  z-index: 2000;
}

.vibrate {
  animation: vibrate 1.5s infinite;
}
@keyframes vibrate {
  0% {
    transform: translate(0);
  }
  25% {
    transform: translate(-2px, 2px);
  }
  50% {
    transform: translate(2px, -2px);
  }
  75% {
    transform: translate(-2px, -2px);
  }
  100% {
    transform: translate(2px, 2px);
  }
}

/* notification style */

/* ===== NOTIFICATION BELL STYLES ===== */

.notification-bell-wrapper {
  display: inline-block;
}

/* Main Bell Container */
.nav-link {
  cursor: pointer;
  padding: 0;
  margin: 0;
  background: transparent;
  transition: all 0.3s ease;
}

.bell-container {
  position: relative;
  padding: 5px;
  border-radius: 50%;
  background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
  transition: all 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
}

.bell-container:hover {
  background: linear-gradient(135deg, #ffffff 0%, #e2e8f0 100%);
  transform: scale(1.08);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.12);
}

.bell-container:active {
  transform: scale(0.96);
}

/* Bell SVG Styling */
.bell-svg {
  fill: none;
  stroke: #64748b;
  stroke-width: 1.2;
  transition: all 0.3s ease;
  display: block;
}

.bell-container:hover .bell-svg {
  stroke: #3b82f6;
  filter: drop-shadow(0 2px 4px rgba(59, 130, 246, 0.3));
  animation: gentleRing 0.6s ease-in-out;
}

.bell-hover {
  background: linear-gradient(135deg, #ffffff 0%, #e2e8f0 100%);
  transform: scale(1.08);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.12);
}

.bell-hover .bell-svg {
  stroke: #eb0707;
  animation: gentleRing 0.6s ease-in-out;
}

/* Gentle ring animation */
@keyframes gentleRing {
  0% {
    transform: rotate(0deg);
  }
  15% {
    transform: rotate(12deg);
  }
  30% {
    transform: rotate(-10deg);
  }
  45% {
    transform: rotate(8deg);
  }
  60% {
    transform: rotate(-6deg);
  }
  75% {
    transform: rotate(4deg);
  }
  85% {
    transform: rotate(-2deg);
  }
  100% {
    transform: rotate(0deg);
  }
}

/* ===== PREMIUM BADGE DESIGN ===== */
.notification-badge {
  position: absolute;
  top: -7px;
  right: -12px;
  z-index: 10;
}

.badge-number {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  background: linear-gradient(135deg, #ef4444 0%, #dc2626 50%, #b91c1c 100%);
  color: white;
  font-size: 11px;
  font-weight: 800;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  border-radius: 20px;
  letter-spacing: 0.3px;
  box-shadow: 0 2px 8px rgba(239, 68, 68, 0.4);
  backdrop-filter: blur(2px);
  transition: all 0.2s ease;
  z-index: 2;
}

/* Badge hover effect */
.bell-container:hover .badge-number {
  transform: scale(1.12);
  box-shadow: 0 3px 12px rgba(239, 68, 68, 0.6);
  background: linear-gradient(135deg, #f97316 0%, #ef4444 50%, #dc2626 100%);
}

/* Badge pulse ring */
.badge-pulse {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100%;
  height: 100%;
  min-width: 20px;
  min-height: 20px;
  background: rgba(239, 68, 68, 0.6);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  animation: badgePulse 1.8s infinite;
  z-index: 1;
}

/* Pulse animation keyframes */
@keyframes badgePulse {
  0% {
    transform: translate(-50%, -50%) scale(0.8);
    opacity: 0.8;
  }
  70% {
    transform: translate(-50%, -50%) scale(1.4);
    opacity: 0;
  }
  100% {
    transform: translate(-50%, -50%) scale(0.8);
    opacity: 0;
  }
}

/* Initial badge pop animation */
@keyframes badgePop {
  0% {
    transform: scale(0);
    opacity: 0;
  }
  60% {
    transform: scale(1.2);
  }
  100% {
    transform: scale(1);
    opacity: 1;
  }
}

.badge-number {
  animation: badgePop 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

/* Optional: Shimmer effect on badge when new notification arrives */
@keyframes badgeShimmer {
  0% {
    background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
  }
  50% {
    background: linear-gradient(135deg, #f97316 0%, #ef4444 100%);
    box-shadow: 0 0 0 4px rgba(239, 68, 68, 0.3);
  }
  100% {
    background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
  }
}

.bell-container:active .badge-number {
  animation: badgeShimmer 0.3s ease;
}

/* Dark mode support */
@media (prefers-color-scheme: dark) {
  .bell-container {
    background: linear-gradient(135deg, #fda9a9ce 0%, #ffffff 100%);
    box-shadow: 0 2px 8px rgba(43, 10, 10, 0.623);
  }

  .bell-container:hover {
    background: linear-gradient(135deg, #f54b4bce 0%, #ffffff 100%);
    box-shadow: 0 2px 8px rgba(43, 10, 10, 0.623);
  }

  .bell-svg {
    stroke: #8d1717;
  }

  .bell-container:hover .bell-svg {
    stroke: #eb0707;
  }
}

/* Mobile responsiveness */
@media (max-width: 768px) {
  .bell-container {
    padding: 8px;
  }

  .bell-svg {
    width: 24px;
    height: 24px;
  }

  .badge-number {
    min-width: 18px;
    height: 18px;
    font-size: 10px;
  }
}

/* Optional: Add a notification count animation for each new notification */
@keyframes countUpdate {
  0% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.3);
    background: linear-gradient(135deg, #f97316 0%, #ef4444 100%);
  }
  100% {
    transform: scale(1);
  }
}

.badge-number.count-changed {
  animation: countUpdate 0.3s ease-out;
}

/* notification style */
